const body = $input.first().json.body || $input.first().json;

// Verificar si es un mensaje entrante de Meta Cloud API
const entry = body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const messages = change?.messages;

if (!messages || messages.length === 0) {
  return []; // Evento de status o entrega, no mensaje
}

const msg = messages[0];
const contact = change.contacts?.[0];
const senderPhone = msg.from; // Ej: 5491155551234
const senderName = contact?.profile?.name || 'Cliente';

let userText = '';
let interactiveId = '';

if (msg.type === 'text') {
  userText = (msg.text?.body || '').trim();
} else if (msg.type === 'interactive') {
  if (msg.interactive.type === 'button_reply') {
    interactiveId = msg.interactive.button_reply.id;
    userText = msg.interactive.button_reply.title;
  } else if (msg.interactive.type === 'list_reply') {
    interactiveId = msg.interactive.list_reply.id;
    userText = msg.interactive.list_reply.title;
  }
}

return [{
  json: {
    senderPhone,
    senderName,
    userText,
    interactiveId,
    rawType: msg.type,
    timestamp: msg.timestamp
  }
}];

const rawInput = $('Parse Incoming Message').first().json;
const redisResult = $input.first().json;

let session = {
  state: 'IDLE',
  barberId: null,
  barberName: null,
  serviceIds: [],
  serviceName: null,
  durationMinutes: 30,
  startTime: null,
  customerId: (rawInput.senderName || 'cliente').toLowerCase().replace(/\s+/g, '-'),
  customerPhone: '+' + rawInput.senderPhone
};

if (redisResult && redisResult.sessionData) {
  try {
    const parsed = typeof redisResult.sessionData === 'string' ? JSON.parse(redisResult.sessionData) : redisResult.sessionData;
    session = Object.assign(session, parsed);
  } catch (e) {}
}

const text = (rawInput.userText || '').toLowerCase();
const actionId = rawInput.interactiveId || '';

if (text === 'hola' || text === 'inicio' || text === 'menu' || text === 'cancelar' || text === 'reiniciar') {
  session.state = 'IDLE';
  session.barberId = null;
  session.serviceIds = [];
}

return [{
  json: {
    ...rawInput,
    session,
    actionId,
    normalizedText: text
  }
}];

const barbers = $input.all().map(i => i.json);
const incoming = $('Session State Manager').first().json;

let barberListText = '👋 ¡Hola *' + incoming.senderName + '*! Bienvenido a *Peluquería Daniel* 💈\n\n¿Con qué barbero te gustaría atenderte?\n\n';

barbers.forEach((b, idx) => {
  barberListText += `${idx + 1}. *${b.fullName}* (${b.specialty})\n`;
});

barberListText += '\n👉 Responde con el número (1, 2 o 3) de tu barbero favorito.';

const nextSession = {
  ...incoming.session,
  state: 'WAITING_BARBER',
  availableBarbers: barbers.map(b => ({ id: b.id, name: b.fullName }))
};

return [{
  json: {
    senderPhone: incoming.senderPhone,
    responseText: barberListText,
    nextSession
  }
}];

const data = $input.first().json;
const text = data.normalizedText;
const actionId = data.actionId;
const available = data.session.availableBarbers || [
  { id: 'barber-daniel', name: 'Daniel Ortiz' },
  { id: 'barber-mateo', name: 'Mateo Silva' },
  { id: 'barber-valentina', name: 'Valentina Rios' }
];

let chosenBarber = null;

if (actionId && actionId.startsWith('barber-')) {
  chosenBarber = available.find(b => b.id === actionId);
} else if (text === '1' || text.includes('daniel')) {
  chosenBarber = available.find(b => b.id.includes('daniel'));
} else if (text === '2' || text.includes('mateo')) {
  chosenBarber = available.find(b => b.id.includes('mateo'));
} else if (text === '3' || text.includes('valentina')) {
  chosenBarber = available.find(b => b.id.includes('valentina'));
}

if (!chosenBarber) {
  return [{
    json: {
      senderPhone: data.senderPhone,
      responseText: '⚠️ No reconocí esa opción. Por favor escribe 1, 2 o 3 para elegir a tu barbero.',
      nextSession: data.session
    }
  }];
}

const servicesText = `✂️ Excelente elección con *${chosenBarber.name}*!\n\n¿Qué servicio deseas agendar?\n\n` +
  `1. *Corte Fade / Degradé* (45 min)\n` +
  `2. *Perfilado de Barba* (30 min)\n` +
  `3. *Combo Completo (Corte Fade + Barba)* (75 min)\n\n` +
  `👉 Escribe 1, 2 o 3 para seleccionar tu servicio.`;

const nextSession = {
  ...data.session,
  state: 'WAITING_SERVICE',
  barberId: chosenBarber.id,
  barberName: chosenBarber.name
};

return [{
  json: {
    senderPhone: data.senderPhone,
    responseText: servicesText,
    nextSession
  }
}];

const data = $input.first().json;
const text = data.normalizedText;

let serviceIds = [];
let serviceName = '';
let durationMinutes = 30;

if (text === '1' || text.includes('fade') || text.includes('corte')) {
  serviceIds = ['corte-fade'];
  serviceName = 'Corte Fade / Degradé';
  durationMinutes = 45;
} else if (text === '2' || text.includes('barba')) {
  serviceIds = ['perfilado-barba'];
  serviceName = 'Perfilado de Barba';
  durationMinutes = 30;
} else if (text === '3' || text.includes('combo')) {
  serviceIds = ['corte-fade', 'perfilado-barba'];
  serviceName = 'Combo Fade + Barba';
  durationMinutes = 75;
} else {
  return [{
    json: {
      senderPhone: data.senderPhone,
      responseText: '⚠️ Opción de servicio no válida. Por favor escribe 1 (Corte), 2 (Barba) o 3 (Combo).',
      nextSession: data.session
    }
  }];
}

const promptDateTime = `💈 Perfecto: *${serviceName}* (${durationMinutes} min) con *${data.session.barberName}*.\n\n` +
  `📅 Ahora, por favor ingresa la fecha y hora que deseas para tu turno.\n` +
  `Formato: *AAAA-MM-DD HH:mm*\n` +
  `Ejemplo: *2026-11-20 16:00*\n\n` +
  `_Nota: Atendemos de Lunes a Sábados de 08:00 a 21:00 hs._`;

const nextSession = {
  ...data.session,
  state: 'WAITING_DATETIME',
  serviceIds,
  serviceName,
  durationMinutes
};

return [{
  json: {
    senderPhone: data.senderPhone,
    responseText: promptDateTime,
    nextSession
  }
}];

const data = $input.first().json;
let rawInput = data.userText.trim();

let cleanDateStr = rawInput.replace(/\//g, '-').replace(' ', 'T');
if (cleanDateStr.length === 16) {
  cleanDateStr += ':00';
}

const parsed = new Date(cleanDateStr);
if (isNaN(parsed.getTime())) {
  return [{
    json: {
      isValid: false,
      senderPhone: data.senderPhone,
      responseText: '❌ Formato de fecha y hora inválido. Usa el formato *AAAA-MM-DD HH:mm* (Ej: *2026-11-20 16:00*).',
      nextSession: data.session
    }
  }];
}

const payload = {
  barberId: data.session.barberId,
  customerId: data.session.customerId || 'cliente-whatsapp',
  customerPhone: data.session.customerPhone,
  serviceIds: data.session.serviceIds,
  startTime: cleanDateStr,
  durationMinutes: data.session.durationMinutes
};

return [{
  json: {
    isValid: true,
    senderPhone: data.senderPhone,
    payload,
    session: data.session
  }
}];

const res = $input.first().json;
const prev = $('Validator & Payload Builder').first().json;
const statusCode = res.statusCode || 200;
const body = res.body || {};

if (statusCode === 201 || (body.id && body.status === 'SCHEDULED')) {
  const confirmMsg = `🎉 *¡TURNO CONFIRMADO CON ÉXITO!* 🎉\n\n` +
    `💈 *Peluquería Daniel*\n` +
    `👤 *Cliente:* ${prev.session.customerId}\n` +
    `✂️ *Servicio:* ${prev.session.serviceName}\n` +
    `👨‍🎨 *Barbero:* ${prev.session.barberName}\n` +
    `📅 *Fecha y Hora:* ${body.startTime.replace('T', ' ')} hs\n` +
    `⏱️ *Duración estimada:* ${body.durationMinutes} minutos\n` +
    `🆔 *Código de Cita:* ${body.id}\n\n` +
    `¡Te esperamos con la mejor atención! 💈✨\n` +
    `_Escribe 'menu' en cualquier momento si deseas agendar otra cita._`;

  return [{
    json: {
      senderPhone: prev.senderPhone,
      responseText: confirmMsg,
      nextSession: { state: 'IDLE' }
    }
  }];
} else {
  const errorDetail = body.detail || 'No se pudo reservar el turno en el horario solicitado.';
  const errorMsg = `⚠️ *No fue posible agendar tu turno:*\n\n👉 ${errorDetail}\n\nPor favor ingresa otro horario (Ej: *2026-11-20 17:00*):`;

  return [{
    json: {
      senderPhone: prev.senderPhone,
      responseText: errorMsg,
      nextSession: prev.session
    }
  }];
}
